starterCode:
// LACUNA: declare e EXPORTE a variável `contador` com `let`, com um valor inicial, no escopo do MÓDULO (fora da função)
export function iniciar() {
  contador = 5;
  return contador;
}

solutionCode:
export let contador = 0;

export function iniciar() {
  contador = 5;
  return contador;
}

testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { iniciar, contador } from './solution.mjs';

test('declara com let no escopo do módulo; a atribuição decide o valor guardado', () => {
  assert.equal(iniciar(), contador);
  assert.equal(iniciar(), contador);
  assert.equal(contador, 5);
});

